          // resets SILENTLY to the default (no last connection), no notice,
          // no migration. The stale file is dropped best-effort so the next
          // save starts clean.
          _connection = null;
          unawaited(env.remove('${env.cwd}/$fileName', force: true));
          return;
        }
        _connection = restored;
      },
    );
  }
}

